#include <iostream>
#include <unordered_map>
using namespace std;
int main() { int n; long long target; cin >> n >> target; unordered_map<long long, long long> frequency; frequency[0] = 1; long long prefix = 0, answer = 0; while (n--) { long long value; cin >> value; prefix += value; auto it = frequency.find(prefix - target); if (it != frequency.end()) answer += it->second; ++frequency[prefix]; } cout << answer << '\n'; }
